import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
const cfg=window.EARLYPASS_CONFIG;
const app=document.querySelector('#app');
const supabase=createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true}});
let user=null,profile=null,classroom=null,students=[],periods=[],weeklySettings=[],timetableReady=false,dayRow=null,page='dashboard',modalNode=null,boardSession=null,selectedDate=null,selectedWeekday=((new Date().getDay()+6)%7)+1,googleToken=null,googleCourses=[],googleRoster=[],googleCourseId='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA').format(new Date());
const time=s=>String(s||'').slice(0,5);
const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const weekdayOf=date=>((new Date((date||today())+'T00:00:00').getDay()+6)%7)+1;
const periodsForDay=day=>{const exact=periods.filter(p=>Number(p.weekday||0)===Number(day));return (exact.length?exact:periods.filter(p=>Number(p.weekday||0)===0)).sort((a,b)=>a.position-b.position)};
const rewardChoices=['Mystery Puzzle','5-Minute Class Game','Team Challenge','Music Choice','Teacher Mystery Challenge','Student Choice Activity'];
const rewardForDate=date=>rewardChoices[(Number(String(date).replaceAll('-',''))||0)%rewardChoices.length];

const daySettings=date=>weeklySettings.find(x=>Number(x.weekday)===weekdayOf(date))||{earlypass_target:classroom?.earlypass_target||25,class_start:classroom?.class_start||'08:30',early_window_minutes:classroom?.early_window_minutes||15};
const toast=m=>{const n=document.createElement('div');n.className='toast';n.textContent=m;document.body.append(n);setTimeout(()=>n.remove(),3200)};
function errMsg(e){return e?.message||'Something went wrong. Please try again.'}
function showError(m){const n=document.querySelector('#msg');if(n){n.className='notice error';n.textContent=m;n.hidden=false}else toast(m)}
function login(){app.innerHTML=`<main class="login-wrap"><section class="login-brand"><div class="brand">early<em>pass</em></div><div class="brand-copy"><h1>Arrive early.<br><em>Unlock something special.</em></h1><p>Small steps from each student add up to something great for the whole class.</p></div><div class="brand-foot">A positive start to every school day.</div></section><section class="login-panel"><form class="login-card" id="login"><div class="eyebrow">EARLYPASS · SECURE ACCOUNT</div><h2>Welcome back</h2><p>Sign in to your EarlyPass class account.</p><div id="msg" class="notice" hidden></div><div class="field"><label for="email">Email</label><input id="email" type="email" autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required></div><button class="primary wide" type="submit">Sign in</button><div class="login-links"><button class="link" type="button" id="forgot">Forgot password?</button><button class="link" type="button" id="signup">Create account</button><a class="link" href="./demo.html">Explore demo</a></div></form></section></main>`;
document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;b.textContent='Signing in…';const {error}=await supabase.auth.signInWithPassword({email:document.querySelector('#email').value.trim(),password:document.querySelector('#password').value});b.disabled=false;b.textContent='Sign in';if(error)showError(errMsg(error));else await boot();};
document.querySelector('#forgot').onclick=async()=>{const email=document.querySelector('#email').value.trim();if(!email){showError('Enter your email above first.');return;}const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)showError(errMsg(error));else{const n=document.querySelector('#msg');n.hidden=false;n.className='notice success';n.textContent='If that account exists, a password reset email is on its way.';}};
document.querySelector('#signup').onclick=()=>signup();
if(location.hash==='#signup')signup();
}
function signup(){
 if(location.hash!=='#signup')history.replaceState(null,'',location.pathname+location.search+'#signup');
 const card=document.querySelector('.login-card');
 if(!card){login();return signup()}
 card.replaceChildren();
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n};
 const makeField=(id,labelText,type='text',required=true)=>{const wrap=el('div','field',''),label=el('label','',labelText),input=document.createElement('input');label.htmlFor=id;input.id=id;input.type=type;input.required=required;wrap.append(label,input);return{wrap,input}};
 const eyebrow=el('div','eyebrow','EARLYPASS · CLASS ACCOUNT');
 const heading=el('h2','','Create your account');
 const intro=el('p','','Free student and teacher accounts. No school administrator approval.');
 const msg=el('div','notice','');msg.id='msg';msg.hidden=true;
 const name=makeField('signup-name','Full name');
 const email=makeField('signup-email','Email','email');
 const roleWrap=el('div','field',''),roleLabel=el('label','','Account type'),role=document.createElement('select');role.id='signup-role';roleLabel.htmlFor=role.id;
 [['STUDENT','Student'],['TEACHER','Teacher / classroom']].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;role.append(option)});roleWrap.append(roleLabel,role);
 const className=makeField('signup-class','Class');
 const section=makeField('signup-section','Section');
 const room=makeField('signup-room','Room', 'text', false);
 const start=makeField('signup-start','Class start time','time');
 const target=makeField('signup-target','Daily early-check-in goal','number');
 const join=makeField('signup-code','Class join code','text');
 join.input.minLength=6;join.input.maxLength=24;join.input.autocomplete='off';join.input.placeholder='At least 6 letters or numbers';
 const teacherFields=el('div','signup-class-fields','');teacherFields.append(className.wrap,section.wrap,room.wrap,start.wrap,target.wrap);
 target.input.min=1;target.input.max=500;target.input.value='25';start.input.value='08:30';
 const password=makeField('signup-password','Password','password'),confirm=makeField('signup-confirm','Confirm password','password');password.input.minLength=8;confirm.input.minLength=8;
 const note=el('div','notice','Teachers create a classroom and share their join code. Students enter their teacher’s code. The class and role are set up automatically.');
 const submit=el('button','primary wide','Create free account');submit.type='submit';
 const links=el('div','login-links',''),back=el('button','link','Already have an account? Sign in');back.type='button';links.append(back);
 card.append(eyebrow,heading,intro,msg,name.wrap,email.wrap,roleWrap,join.wrap,teacherFields,password.wrap,confirm.wrap,note,submit,links);
 const updateFields=()=>{const teacher=role.value==='TEACHER';teacherFields.hidden=!teacher;className.input.required=teacher;section.input.required=teacher;start.input.required=teacher;target.input.required=teacher;join.wrap.querySelector('label').textContent=teacher?'Choose a class join code':'Class join code from your teacher';join.input.placeholder=teacher?'Create a code students can enter':'Enter the code shared by your teacher'};
 role.onchange=updateFields;updateFields();
 back.onclick=()=>{history.replaceState(null,'',location.pathname+location.search+'#login');login()};
 card.onsubmit=async e=>{
  e.preventDefault();if(password.input.value!==confirm.input.value){showError('The passwords do not match.');confirm.input.focus();return}
  submit.disabled=true;submit.textContent='Creating account…';
  const metadata={display_name:name.input.value.trim(),requested_role:role.value,class_name:className.input.value.trim(),section:section.input.value.trim(),room:room.input.value.trim(),class_start:start.input.value,earlypass_target:Number(target.input.value||25),class_join_code:join.input.value.trim()};
  const {data,error}=await supabase.auth.signUp({email:email.input.value.trim(),password:password.input.value,options:{data:metadata}});
  submit.disabled=false;submit.textContent='Create free account';
  if(error){showError(errMsg(error));return}
  if(data?.session){await boot();return}
  const notice=document.querySelector('#msg');notice.hidden=false;notice.className='notice success';notice.textContent='Account created. Confirm your email if asked, then sign in. Your teacher class or student membership will be set up automatically. No administrator approval is needed.';
 };
}
function shell(){const nav=profile.role==='STUDENT'?[['student','My dashboard'],['history','My attendance'],['arrivals','My early arrivals'],['board','Class progress']]:[['dashboard','Dashboard'],['students','Students'],['attendance','Attendance'],['periods','Periods'],['timetable','Weekly timetable'],['earlypass','EarlyPass'],['board','Classroom board'],['settings','Settings']];
app.innerHTML=`<div class="layout"><aside class="side"><div class="side-head"><div class="brand">early<em>pass</em></div><button class="close-menu secondary" id="close-menu" type="button" aria-label="Close dashboard menu">✕</button></div><div class="school"><b>${esc(classroom.class_name)}${esc(classroom.section)}</b><small>${esc(profile.role)} · ${esc(profile.display_name)}</small></div><nav class="nav">${nav.map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${label}</button>`).join('')}</nav><div class="side-bottom"><div class="account"><span class="avatar">${esc((profile.display_name||'?').slice(0,1).toUpperCase())}</span><span><b>${esc(profile.display_name)}</b><small>${esc(profile.role)}</small></span><button id="logout" class="logout">Sign out</button></div></div></aside><main class="main"><header class="top"><button class="mobile-menu secondary" id="menu">☰</button><span>${esc(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</span><span class="online">● Secure account</span></header><section class="content" id="content"></section></main></div><div id="modal-root"></div>`;
document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{page=x.dataset.page;render()});document.querySelector('#logout').onclick=async()=>{await supabase.auth.signOut();profile=null;classroom=null;login()};document.querySelector('#menu').onclick=()=>{const layout=document.querySelector('.layout'),side=document.querySelector('.side');if(matchMedia('(max-width: 940px)').matches)side.classList.toggle('show');else layout.classList.toggle('sidebar-closed')};document.querySelector('#close-menu').onclick=()=>document.querySelector('.side').classList.remove('show');
}
async function presentCountForDay(){if(!dayRow)return 0;const first=periodsForDay(weekdayOf(today()))[0];if(!first)return 0;const {data,error}=await supabase.from('attendance').select('student_id,status').eq('class_day_id',dayRow.id).eq('period_id',first.id).in('status',['PRESENT','LATE']);if(error)throw error;return new Set((data||[]).map(x=>x.student_id)).size}
async function dailyGoal(){if(!dayRow)return{target:Math.max(1,students.length||classroom.earlypass_target||1),reward:rewardForDate(today()),follow_up:'A brief reflection and a fresh start tomorrow.'};const {data:r,error}=await supabase.from('earlypass_rewards').select('target,reward,manual_target,follow_up').eq('class_day_id',dayRow.id).maybeSingle();if(error)throw error;const present=await presentCountForDay(),target=r?.manual_target?Number(r.target):Math.max(1,present||students.length||classroom.earlypass_target||1);return{...r,target,reward:r?.reward||rewardForDate(today()),follow_up:r?.follow_up||'A brief reflection and a fresh start tomorrow.'}}
async function loadDay(forDate=today()){const settings=daySettings(forDate);let q=await supabase.from('class_days').select('*').eq('classroom_id',classroom.id).eq('day',forDate).maybeSingle();if(q.error)throw q.error;dayRow=q.data;if(!dayRow&&profile.role!=='STUDENT'&&forDate===today()){const ins=await supabase.from('class_days').insert({classroom_id:classroom.id,day:forDate,reward:rewardForDate(forDate)}).select().single();if(ins.error)throw ins.error;dayRow=ins.data}if(dayRow&&profile.role!=='STUDENT'){const existing=await supabase.from('earlypass_rewards').select('id').eq('class_day_id',dayRow.id).maybeSingle();if(existing.error)throw existing.error;if(!existing.data){const initialTarget=Math.max(1,students.length||settings.earlypass_target||classroom.earlypass_target||1);const goal=await supabase.from('earlypass_rewards').insert({class_day_id:dayRow.id,target:initialTarget,reward:rewardForDate(forDate),manual_target:false,follow_up:'A brief reflection and a fresh start tomorrow.'});if(goal.error)throw goal.error}}}
async function loadShared(){const [s,p,w]=await Promise.all([supabase.from('students').select('*').eq('classroom_id',classroom.id).eq('active',true).order('roll_number'),supabase.from('periods').select('*').eq('classroom_id',classroom.id).order('position'),supabase.from('weekly_settings').select('*').eq('classroom_id',classroom.id)]);if(s.error)throw s.error;if(p.error)throw p.error;students=s.data||[];periods=p.data||[];timetableReady=!w.error;weeklySettings=w.data||[];await loadDay()}
function completeClassSetup(message=''){
 const meta=user?.user_metadata||{},oldRole=['STUDENT','TEACHER'].includes(meta.requested_role)?meta.requested_role:'STUDENT';
 app.innerHTML='';
 const wrap=document.createElement('main');wrap.className='login-wrap';
 const panel=document.createElement('section');panel.className='login-panel';
 const form=document.createElement('form');form.className='login-card';
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n};
 const field=(id,labelText,type='text',required=true,value='')=>{const box=el('div','field'),label=el('label','',labelText),input=document.createElement('input');label.htmlFor=id;input.id=id;input.name=id;input.type=type;input.required=required;input.value=value||'';box.append(label,input);return{box,input}};
 const heading=el('h2','','Finish setting up EarlyPass');
 const intro=el('p','','Choose Teacher to create a class, or Student to join a class. No school administrator approval is needed.');
 const notice=el('div',message?'notice error':'notice',message);notice.hidden=!message;
 const roleBox=el('div','field'),roleLabel=el('label','','Account type'),role=document.createElement('select');roleLabel.htmlFor='setup-role';role.id='setup-role';[['STUDENT','Student'],['TEACHER','Teacher / classroom']].forEach(([v,t])=>{const o=document.createElement('option');o.value=v;o.textContent=t;role.append(o)});role.value=oldRole;roleBox.append(roleLabel,role);
 const name=field('setup-name','Full name','text',true,meta.display_name||user?.email?.split('@')[0]||'');
 const className=field('setup-class','Class','text',false,meta.class_name||'');
 const section=field('setup-section','Section','text',false,meta.section||'');
 const room=field('setup-room','Room','text',false,meta.room||'');
 const start=field('setup-start','Class start time','time',false,meta.class_start||'08:30');
 const target=field('setup-target','Daily early-check-in goal','number',false,String(meta.earlypass_target||25));target.input.min=1;target.input.max=500;
 const code=field('setup-code','Class join code','text',true,meta.class_join_code||'');code.input.minLength=6;code.input.maxLength=24;code.input.autocomplete='off';
 const teacherFields=el('div','signup-class-fields');teacherFields.append(className.box,section.box,room.box,start.box,target.box);
 const submit=el('button','primary wide','Save and continue');submit.type='submit';
 const signout=el('button','link','Sign out');signout.type='button';signout.onclick=async()=>{await supabase.auth.signOut();user=null;login()};
 const update=()=>{const isTeacher=role.value==='TEACHER';teacherFields.hidden=!isTeacher;className.input.required=isTeacher;section.input.required=isTeacher;start.input.required=isTeacher;target.input.required=isTeacher;code.box.querySelector('label').textContent=isTeacher?'Create a class join code':'Class join code from your teacher';code.input.placeholder=isTeacher?'At least 6 characters; share it with your students':'Enter the code shared by your teacher'};
 role.onchange=update;update();
 form.append(el('div','eyebrow','EARLYPASS · CLASS ACCOUNT'),heading,intro,notice,roleBox,name.box,code.box,teacherFields,submit,signout);
 panel.append(form);wrap.append(panel);app.append(wrap);
 form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;submit.textContent='Setting up…';const data={...meta,display_name:name.input.value.trim(),requested_role:role.value,class_name:className.input.value.trim(),section:section.input.value.trim(),room:room.input.value.trim(),class_start:start.input.value,earlypass_target:Number(target.input.value||25),class_join_code:code.input.value.trim()};const updated=await supabase.auth.updateUser({data});if(updated.error){notice.hidden=false;notice.textContent=errMsg(updated.error);submit.disabled=false;submit.textContent='Save and continue';return}user=updated.data.user||user;const provision=await supabase.rpc('complete_class_signup');if(provision.error){notice.hidden=false;notice.textContent=errMsg(provision.error);submit.disabled=false;submit.textContent='Save and continue';return}await boot()};
}
async function boot(){const {data:{user:u}}=await supabase.auth.getUser();user=u;if(!u){login();return}let {data:p,error}=await supabase.from('profiles').select('*').eq('user_id',u.id).maybeSingle();if(error){login();showError(errMsg(error));return}if(!p){const provision=await supabase.rpc('complete_class_signup');if(provision.error){completeClassSetup(provision.error.message);return}const refreshed=await supabase.from('profiles').select('*').eq('user_id',u.id).maybeSingle();p=refreshed.data;error=refreshed.error;if(error||!p){completeClassSetup(error?errMsg(error):'Setup did not complete. Please try again.');return}}profile=p;
if(p.role==='STUDENT'){const {data:s,error:se}=await supabase.from('students').select('*').eq('id',p.student_id).single();if(se||!s){await supabase.auth.signOut();login();showError(se?errMsg(se):'No student profile is linked to this account.');return}const {data:c,error:ce}=await supabase.from('classrooms').select('*').eq('id',s.classroom_id).single();if(ce){login();showError(errMsg(ce));return}classroom=c;students=[s];const {data:ps}=await supabase.from('periods').select('*').eq('classroom_id',c.id).order('position');periods=ps||[];const {data:d}=await supabase.from('class_days').select('*').eq('classroom_id',c.id).eq('day',today()).maybeSingle();dayRow=d}
else if(p.role==='ADMIN'){const {data:c,error:ce}=await supabase.from('classrooms').select('*').eq('school_id',p.school_id).limit(1).maybeSingle();if(ce||!c){login();showError(ce?errMsg(ce):'No classroom is set up for this school yet.');return}classroom=c;await loadShared()}else {const {data:t,error:te}=await supabase.from('classroom_teachers').select('classroom_id, classrooms(*)').eq('user_id',u.id).limit(1).maybeSingle();if(te||!t?.classrooms){login();showError(te?errMsg(te):'No class is assigned to this teacher account yet. Ask an administrator to assign your classroom.');return}classroom=t.classrooms;await loadShared()}
shell();render()}
function title(a,b,action=''){return `<div class="page-title"><div><h1>${a}</h1><p>${b}</p></div>${action}</div>`}
function card(a,b){return `<article class="card metric"><label>${a}</label><strong>${b}</strong></article>`}
async function render(){if(!profile)return;if(page==='board'&&!boardSession){boardView();return}try{if(profile.role!=='STUDENT')await loadShared();else if(['student','history','arrivals'].includes(page)){/* RLS limits queries to the linked student. */}const c=document.querySelector('#content');if(!c)return;c.innerHTML=page==='students'?await studentsPage():page==='attendance'?await attendancePage():page==='periods'?periodsPage():page==='timetable'?timetablePage():page==='earlypass'?await earlyPage():page==='settings'?settingsPage():page==='history'?await studentHistory():page==='arrivals'?await studentArrivals():page==='student'?await studentHome():page==='board'?boardView():await dashboard();const dateInput=document.querySelector('#att-date');if(dateInput)dateInput.onchange=()=>{selectedDate=dateInput.value||today();render()};const weeklyForm=document.querySelector('#weekly-settings');if(weeklyForm)weeklyForm.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(weeklyForm)),payload={classroom_id:classroom.id,weekday:selectedWeekday,class_start:v.class_start,early_window_minutes:Number(v.early_window_minutes),earlypass_target:Number(v.earlypass_target)};const {error}=await supabase.from('weekly_settings').upsert(payload,{onConflict:'classroom_id,weekday'});if(error){showError(errMsg(error));return}weeklySettings=weeklySettings.filter(x=>Number(x.weekday)!==selectedWeekday).concat(payload);if(selectedWeekday===weekdayOf(today())&&dayRow){const goal=await supabase.from('earlypass_rewards').upsert({class_day_id:dayRow.id,target:payload.earlypass_target,reward:'Mystery Puzzle'},{onConflict:'class_day_id'});if(goal.error){showError(errMsg(goal.error));return}}toast(weekdays[selectedWeekday-1]+' goal and times saved.');render()};const googleClientForm=document.querySelector('#google-client-form');if(googleClientForm)googleClientForm.onsubmit=e=>{e.preventDefault();const id=new FormData(googleClientForm).get('client_id').trim();if(id)localStorage.setItem('earlypass-google-client-id',id);else localStorage.removeItem('earlypass-google-client-id');toast('Google OAuth client ID saved on this device.');render()};const googleConnectButton=document.querySelector('#google-connect');if(googleConnectButton)googleConnectButton.onclick=()=>connectGoogle();const googleRosterButton=document.querySelector('#google-load-roster');if(googleRosterButton)googleRosterButton.onclick=()=>loadGoogleCourse().catch(e=>showError(errMsg(e)));const googleSyncButton=document.querySelector('#google-sync-roster');if(googleSyncButton)googleSyncButton.onclick=()=>syncGoogleRoster().catch(e=>showError(errMsg(e)));const f=document.querySelector('#student-filter');if(f)f.oninput=()=>{document.querySelectorAll('[data-name]').forEach(r=>r.hidden=!r.dataset.name.includes(f.value.toLowerCase()))}}catch(e){document.querySelector('#content').innerHTML=`<div class="notice error">${esc(errMsg(e))}</div>`}}
async function counts(){if(!dayRow)return{arr:[],att:[]};const [a,t]=await Promise.all([supabase.from('arrivals').select('status').eq('class_day_id',dayRow.id),supabase.from('attendance').select('status').eq('class_day_id',dayRow.id)]);if(a.error)throw a.error;if(t.error)throw t.error;return{arr:a.data||[],att:t.data||[]}}
async function dashboard(){const {arr,att}=await counts(),goal=await dailyGoal(),early=arr.filter(x=>x.status==='EARLY').length,target=goal.target,unlocked=early>=target,present=await presentCountForDay();return title('Good morning, '+esc(profile.display_name),'A positive start for '+esc(classroom.class_name)+esc(classroom.section),'<button class="primary" data-action="attendance">Take attendance</button>')+'<div class="grid metrics">'+card('Early check-ins',early+' / '+target)+card('Students present',present)+card('Periods today',periodsForDay(weekdayOf(today())).length)+card('Attendance marks',att.length)+'</div><div class="grid twocol"><section class="card"><div class="eyebrow">TODAY\'S EARLYPASS</div><h2>'+(unlocked?'🎉 EarlyPass unlocked!':'Small steps, big team energy.')+'</h2><p class="muted">'+(unlocked?'The class reward is ready.':'Every early arrival adds to the team goal.')+'</p><div class="progress"><i style="width:'+Math.min(100,early/target*100)+'%"></i></div><b>'+early+' / '+target+'</b> students checked in early</section><section class="card reward"><div class="eyebrow">TODAY\'S CLASS ACTIVITY</div><h2>'+esc(unlocked?goal.reward:'A little mystery awaits')+'</h2><p>'+(unlocked?'The class reached its shared goal.':'The activity stays secret until the goal is reached.')+'</p><button class="secondary" data-action="board">Open classroom board</button></section></div>'}

async function studentsPage(){return title('Students','Manage the roster for your assigned class.',`<button class="primary" data-action="add-student">＋ Add student</button>`)+`<section class="card"><div class="toolbar"><input id="student-filter" class="search" placeholder="Search name, roll or student ID"><span class="muted">${students.length} students</span></div><div class="table-wrap"><table class="table"><thead><tr><th>STUDENT</th><th>ROLL</th><th>STUDENT ID</th><th>EMAIL</th><th></th></tr></thead><tbody>${students.map(s=>`<tr data-name="${esc((s.name+' '+s.roll_number+' '+s.student_code).toLowerCase())}"><td><b>${esc(s.name)}</b></td><td>${esc(s.roll_number)}</td><td>${esc(s.student_code)}</td><td>${esc(s.email||'—')}</td><td><button class="secondary" data-action="edit-student" data-id="${s.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No students yet. Add your first class member.</td></tr>'}</tbody></table></div></section>`}
async function attendancePage(){selectedDate=selectedDate||today();await loadDay(selectedDate);if(!dayRow)return title('Attendance','No class session exists for this date.')+'<div class="empty">There are no attendance records for this date.</div>';const {data:rows,error}=await supabase.from('attendance').select('student_id,period_id,status').eq('class_day_id',dayRow.id);if(error)throw error;let index=new Map((rows||[]).map(r=>[r.student_id+':'+r.period_id,r.status]));const dayPeriods=periodsForDay(weekdayOf(selectedDate));return title('Attendance','Mark attendance for every period. Only teachers can make changes.',`<input id="att-date" class="search" type="date" value="${esc(selectedDate)}">`)+`<section class="card"><div class="toolbar"><b>Daily attendance · ${esc(selectedDate)}</b><span class="muted">Tap a status to cycle</span></div><div class="table-wrap"><table class="table"><thead><tr><th>ROLL</th><th>STUDENT</th>${dayPeriods.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.roll_number)}</td><td><b>${esc(s.name)}</b></td>${dayPeriods.map(p=>{let st=index.get(s.id+':'+p.id)||'';return `<td><button class="status ${st}" data-action="cycle" data-id="${s.id}|${p.id}">${st==='PRESENT'?'✓':st==='LATE'?'L':st==='ABSENT'?'A':st==='EXCUSED'?'E':'—'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">Present · Late · Absent · Excused</p></section>`}
function periodsPage(){return title('Periods','Manage period details. Set a different schedule for each weekday in Weekly timetable.',`<button class="primary" data-action="add-period">＋ Add period</button>`)+`<section class="card">${periods.map((p,i)=>`<div class="period-row"><b>${String(i+1).padStart(2,'0')}</b><div><b>${esc(p.subject||p.name)}</b><small class="muted"> · ${esc(p.name)}</small></div><span>${esc(time(p.starts_at))} – ${esc(time(p.ends_at))}</span><span>${esc(p.room||classroom.room)}</span><div class="inline"><button class="secondary" data-action="edit-period" data-id="${p.id}">Edit</button><button class="danger" data-action="delete-period" data-id="${p.id}">Delete</button></div></div>`).join('')||'<div class="empty">Add periods to begin.</div>'}</section>`}
function timetablePage(){const d=selectedWeekday,cfg=weeklySettings.find(x=>Number(x.weekday)===d)||{class_start:classroom.class_start,early_window_minutes:classroom.early_window_minutes,earlypass_target:classroom.earlypass_target},dayPeriods=periodsForDay(d);return title('Weekly timetable','Set period times and the EarlyPass goal for each day.')+`<section class="card"><div class="weekday-tabs">${weekdays.map((name,i)=>`<button class="${d===i+1?'active':''}" data-action="choose-weekday" data-id="${i+1}">${name}</button>`).join('')}</div>${timetableReady?`<form id="weekly-settings" class="form-row"><div class="field"><label>Class starts</label><input name="class_start" type="time" value="${esc(time(cfg.class_start))}" required></div><div class="field"><label>Early arrival window (minutes)</label><input name="early_window_minutes" type="number" min="1" max="180" value="${esc(cfg.early_window_minutes)}" required></div><div class="field"><label>EarlyPass target</label><input name="earlypass_target" type="number" min="1" value="${esc(cfg.earlypass_target)}" required></div><button class="primary wide" style="grid-column:1/-1">Save ${weekdays[d-1]} goal and times</button></form>`:'<div class="notice error">Weekly timetable storage is not set up yet. Run the migration linked in the project repository, then refresh this page.</div>'}</section><section class="card" style="margin-top:18px"><div class="toolbar"><div><h2>${weekdays[d-1]} periods</h2><p class="muted">${dayPeriods.length} periods configured</p></div><button class="primary" data-action="add-period">＋ Add period</button></div>${dayPeriods.map((p,i)=>`<div class="period-row"><b>${String(i+1).padStart(2,'0')}</b><div><b>${esc(p.subject||p.name)}</b><small class="muted"> · ${esc(p.name)}</small></div><span>${esc(time(p.starts_at))} – ${esc(time(p.ends_at))}</span><span>${esc(p.room||classroom.room)}</span><div class="inline"><button class="secondary" data-action="edit-period" data-id="${p.id}">Edit</button><button class="danger" data-action="delete-period" data-id="${p.id}">Delete</button></div></div>`).join('')||'<div class="empty">No periods for this day. Add a period to build this day’s timetable.</div>'}</section>`}
async function earlyPage(){const {arr}=await counts(),goal=await dailyGoal(),early=arr.filter(x=>x.status==='EARLY').length,target=goal.target,unlocked=early>=target,settings=daySettings(today()),now=new Date(),start=String(settings.class_start||'08:30').slice(0,5),afterStart=now.getHours()*60+now.getMinutes()>=Number(start.slice(0,2))*60+Number(start.slice(3,5)),present=await presentCountForDay();return title('EarlyPass','Today’s goal follows first-period attendance and can be adjusted for today.','<button class="secondary" data-action="edit-goal">⚙ Edit today’s goal</button>')+'<div class="grid twocol"><section class="card"><div class="eyebrow">TODAY\'S EARLYPASS</div><h2>'+(unlocked?'🎉 EARLYPASS UNLOCKED!':'Arrive early. Unlock something special.')+'</h2><div class="progress"><i style="width:'+Math.min(100,early/target*100)+'%"></i></div><div class="board-count">'+early+' <span>/ '+target+'</span></div><p class="muted">'+(unlocked?'The whole class earned today’s activity.':Math.max(0,target-early)+' more early check-ins needed.')+'</p><p class="muted">Goal source: '+(goal.manual_target?'Teacher-edited for today':present+' students marked present in Period 1')+'.</p></section><section class="card reward"><div class="eyebrow">TODAY\'S CLASS ACTIVITY</div><h2>'+esc(unlocked?goal.reward:'Mystery activity')+'</h2><p>'+(unlocked?'Unlocked for the whole class.':'The activity stays secret until the goal is reached.')+'</p><p class="muted">If the minimum is missed, teacher-only follow-up: '+esc(goal.follow_up)+'</p>'+(!unlocked&&afterStart?'<button class="secondary" data-action="review-follow-up">Review private follow-up</button>':'')+'</section></div>'}

const getGoogleClientId=()=>localStorage.getItem('earlypass-google-client-id')||cfg.googleClientId||'';
function loadGoogleIdentity(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.oauth2){resolve();return}let tag=document.querySelector('script[data-google-identity]');if(!tag){tag=document.createElement('script');tag.src='https://accounts.google.com/gsi/client';tag.async=true;tag.defer=true;tag.dataset.googleIdentity='true';document.head.append(tag)}tag.onload=()=>resolve();tag.onerror=()=>reject(new Error('Could not load Google sign-in. Check your internet connection.'))})}
async function connectGoogle(){if(!getGoogleClientId()){showError('Add your Google OAuth Web Client ID and save it first.');return}try{await loadGoogleIdentity();const client=google.accounts.oauth2.initTokenClient({client_id:getGoogleClientId(),scope:'https://www.googleapis.com/auth/classroom.courses.readonly https://www.googleapis.com/auth/classroom.rosters.readonly https://www.googleapis.com/auth/classroom.profile.emails',callback:async response=>{if(response.error){googleToken=null;showError('Google authorization failed: '+response.error);return}googleToken=response.access_token;try{googleCourses=await googleApiList('https://classroom.googleapis.com/v1/courses?courseStates=ACTIVE&pageSize=100','courses');googleRoster=[];googleCourseId='';toast('Google Classroom connected for this session.');render()}catch(e){showError(errMsg(e))}}});client.requestAccessToken({prompt:'consent'})}catch(e){showError(errMsg(e))}}
async function googleApiList(url,key){const items=[];let next=url;while(next){const res=await fetch(next,{headers:{Authorization:'Bearer '+googleToken}}),body=await res.json();if(!res.ok)throw new Error(body.error?.message||'Google Classroom could not load this information.');items.push(...(body[key]||[]));next=body.nextPageToken?url.split('?')[0]+'?'+new URLSearchParams({...Object.fromEntries(new URL(url).searchParams),pageToken:body.nextPageToken}):null}return items}
async function loadGoogleCourse(){const select=document.querySelector('#google-course');if(!select?.value)return;googleCourseId=select.value;googleRoster=await googleApiList('https://classroom.googleapis.com/v1/courses/'+encodeURIComponent(googleCourseId)+'/students?pageSize=100','students');render()}
async function syncGoogleRoster(){if(!googleToken||!googleCourseId||!googleRoster.length){showError('Connect Google Classroom and preview a course roster first.');return}const loaded=await supabase.from('students').select('id,name,email,roll_number,student_code,google_student_id').eq('classroom_id',classroom.id);if(loaded.error){showError(errMsg(loaded.error));return}const existing=loaded.data||[],rolls=new Set(existing.map(s=>String(s.roll_number))),codes=new Set(existing.map(s=>s.student_code)),updates=[],inserts=[];let nextRoll=Math.max(0,...existing.map(s=>parseInt(s.roll_number,10)||0))+1;for(const item of googleRoster){const profile=item.profile||{},name=(profile.name?.fullName||[profile.name?.givenName,profile.name?.familyName].filter(Boolean).join(' ')||profile.emailAddress||'Google Classroom student').trim(),email=profile.emailAddress||null;let match=existing.find(s=>s.google_student_id===item.userId)||(email?existing.find(s=>(s.email||'').toLowerCase()===email.toLowerCase()):null);if(match){updates.push({id:match.id,name,email:email||match.email,google_student_id:item.userId});continue}let roll;do{roll=String(nextRoll++).padStart(2,'0')}while(rolls.has(roll));rolls.add(roll);let code;do{code='EP-'+classroom.class_name+classroom.section+'-'+String(nextRoll-1).padStart(3,'0');if(codes.has(code))nextRoll++}while(codes.has(code));codes.add(code);inserts.push({school_id:classroom.school_id,classroom_id:classroom.id,name,email,google_student_id:item.userId,roll_number:roll,student_code:code,active:true})}for(const update of updates){const {id,...payload}=update;const q=await supabase.from('students').update(payload).eq('id',id);if(q.error){showError(errMsg(q.error));return}}if(inserts.length){const {error}=await supabase.from('students').insert(inserts);if(error){showError(errMsg(error));return}}await loadShared();googleRoster=[];googleCourseId='';toast('Google Classroom sync complete: '+(updates.length+inserts.length)+' students matched or imported.');render()}
function settingsPage(){const clientId=getGoogleClientId();return title('Settings','Class settings and authorized integrations.')+`<div class="grid twocol"><section class="card"><div class="eyebrow">CLASS DETAILS</div><h2>${esc(classroom.class_name)}${esc(classroom.section)} · ${esc(classroom.room)}</h2><p class="muted">Starts at ${esc(time(classroom.class_start))}</p><p class="muted">Student join code: <b>${esc(user?.user_metadata?.class_join_code||'Not set yet')}</b></p><button class="secondary" data-action="edit-join-code">Set or change join code</button> <button class="secondary" data-action="edit-class">Edit class settings</button></section><section class="card"><div class="eyebrow">CLASSROOM BOARD</div><h2>Protected shared display</h2><p class="muted">Configure a classroom access code of at least 12 characters. Students share this board; no personal attendance is shown there.</p><button class="secondary" data-action="board">Open classroom board</button></section></div><section class="card" style="margin-top:18px"><div class="eyebrow">GOOGLE CLASSROOM</div><h2>Connect a real Google Classroom</h2><p class="muted">${googleToken?'Connected for this session.':clientId?'OAuth client ID saved; Google Classroom is not connected yet.':'Google Classroom connection not configured.'} Demo mode is separate and does not claim a live connection.</p><form id="google-client-form" class="inline"><div class="field" style="flex:1;min-width:260px"><label for="google-client-id">Google OAuth Web Client ID</label><input id="google-client-id" name="client_id" type="text" value="${esc(clientId)}" placeholder="123...apps.googleusercontent.com"></div><button class="secondary">Save client ID</button></form><div class="inline"><button class="primary" id="google-connect" ${clientId?'':'disabled'}>Connect Google Classroom</button>${googleToken?'<span class="badge">Connected</span>':''}</div><p class="muted">Setup required: enable the Google Classroom API, create a Web OAuth client, add <code>https://ksubhashchandra19-stack.github.io</code> as an authorized JavaScript origin, and add your Google account as a test user if the app is in testing.</p><div class="notice">Before importing students, run the latest <a href="https://github.com/ksubhashchandra19-stack/earlypass/blob/main/supabase/weekly-timetable-migration.sql" target="_blank" rel="noreferrer">database migration</a>. Sync imports class roster details only; it does not create student login accounts.</div>${googleToken?`<div class="inline" style="margin-top:12px"><select id="google-course" class="search"><option value="">Select an active course</option>${googleCourses.map(c=>`<option value="${esc(c.id)}" ${c.id===googleCourseId?'selected':''}>${esc(c.name)}${c.section?' · '+esc(c.section):''}</option>`).join('')}</select><button class="secondary" id="google-load-roster">Preview students</button></div>${googleRoster.length?`<p class="muted">Preview · ${googleRoster.length} students. Existing EarlyPass students will be matched by Google ID or email.</p><div class="table-wrap" style="max-height:240px"><table class="table"><thead><tr><th>NAME</th><th>EMAIL</th></tr></thead><tbody>${googleRoster.map(s=>`<tr><td>${esc(s.profile?.name?.fullName||s.profile?.emailAddress||'Student')}</td><td>${esc(s.profile?.emailAddress||'—')}</td></tr>`).join('')}</tbody></table></div><button class="primary" id="google-sync-roster">Confirm and sync ${googleRoster.length} students</button>`:''}`:''}</section><section class="card" style="margin-top:18px"><div class="eyebrow">ACCOUNT & PERMISSIONS</div><p class="muted">Signed in as ${esc(profile.role)}. Role permissions come from your school-managed profile. Student accounts cannot change attendance or class settings.</p></section>`}
async function studentRows(){const {data:a,error}=await supabase.from('attendance').select('class_day_id,period_id,status,marked_at').eq('student_id',profile.student_id).order('marked_at',{ascending:false});if(error)throw error;return a||[]}
async function studentEarlyStreak(){const {data:a,error}=await supabase.from('arrivals').select('class_day_id,status').eq('student_id',profile.student_id).eq('status','EARLY');if(error)throw error;const ids=[...new Set((a||[]).map(x=>x.class_day_id))];if(!ids.length)return{current:0,best:0};const {data:d,error:de}=await supabase.from('class_days').select('id,day').in('id',ids);if(de)throw de;const dates=new Set((d||[]).map(x=>x.day));const shift=(s,n)=>{const q=new Date(s+'T12:00:00Z');q.setUTCDate(q.getUTCDate()+n);return q.toISOString().slice(0,10)},prevSchool=s=>{let q=shift(s,-1);while(weekdayOf(q)>5)q=shift(q,-1);return q};let last=today();while(weekdayOf(last)>5)last=shift(last,-1);let current=0;if(dates.has(last)){current=1;let q=prevSchool(last);while(dates.has(q)){current++;q=prevSchool(q)}}const sorted=[...dates].sort().reverse();let best=0,run=0,prior=null;for(const day of sorted){run=prior&&prevSchool(prior)===day?run+1:1;best=Math.max(best,run);prior=day}return{current,best}}
async function studentHome(){const s=students[0],a=await studentRows(),streak=await studentEarlyStreak(),percent=a.length?Math.round(a.filter(x=>x.status==='PRESENT'||x.status==='LATE').length/a.length*100):0;return title('My dashboard',`Welcome, ${esc(s.name)}.`)+`<div class="grid metrics">${card('Student ID',esc(s.student_code))}${card('Roll number',esc(s.roll_number))}${card('Attendance',percent+'%')}${card('Early-arrival streak',streak.current+' days')}</div><section class="card"><h2>Your progress</h2><p class="muted">Your best early-arrival streak is ${streak.best} school days. Keep showing up and taking part.</p><button class="secondary" data-action="history">View my attendance</button></section>`}
async function studentHistory(){const rows=await studentRows();const days=rows.map(x=>x.class_day_id);let dates={};if(days.length){const {data:d}=await supabase.from('class_days').select('id,day').in('id',[...new Set(days)]);for(const x of d||[])dates[x.id]=x.day}return title('My attendance','Your own period-by-period history.')+`<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>DATE</th><th>PERIOD</th><th>STATUS</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(dates[r.class_day_id]||'—')}</td><td>${esc(periods.find(p=>p.id===r.period_id)?.name||'Period')}</td><td><span class="badge">${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="3" class="empty">No attendance history yet.</td></tr>'}</tbody></table></div></section>`}
async function studentArrivals(){const {data:a,error}=await supabase.from('arrivals').select('class_day_id,status,arrived_at').eq('student_id',profile.student_id).order('arrived_at',{ascending:false});if(error)throw error;const ids=[...new Set((a||[]).map(x=>x.class_day_id))],map={};if(ids.length){const {data:d}=await supabase.from('class_days').select('id,day').in('id',ids);for(const x of d||[])map[x.id]=x.day}const streak=await studentEarlyStreak();return title('My early arrivals','Your personal history stays private.')+`<section class="card"><div class="inline"><span class="badge">Current streak · ${streak.current} school days</span><span class="badge">Best streak · ${streak.best} school days</span></div><div class="table-wrap" style="margin-top:16px"><table class="table"><thead><tr><th>DATE</th><th>ARRIVAL</th><th>STATUS</th></tr></thead><tbody>${(a||[]).map(x=>`<tr><td>${esc(map[x.class_day_id]||'—')}</td><td>${esc(new Date(x.arrived_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}</td><td><span class="badge">${esc(x.status)}</span></td></tr>`).join('')||'<tr><td colspan="3" class="empty">No arrival history yet.</td></tr>'}</tbody></table></div></section>`}
function boardView(){const c=document.querySelector('#content');if(!c)return;c.innerHTML=title('Classroom board','Shared class progress. No names or personal attendance are shown.','<button class="secondary" data-action="board-fullscreen">⛶ Board display</button>')+'<div class="board-wrap"><section class="board"><button class="board-exit" data-action="board-exit">Exit board display</button><div class="brand">early<em>pass</em> <span class="badge">CLASS '+esc(classroom.class_name)+esc(classroom.section)+'</span></div><div class="eyebrow" style="color:#a8ecc9;margin-top:50px">GOOD MORNING, CLASS '+esc(classroom.class_name)+esc(classroom.section)+'!</div><h1>Arrive early.<br><em>Unlock something special.</em></h1><p class="board-count" id="board-progress">— <span>/ —</span></p><div class="progress"><i id="board-fill" style="width:0%"></i></div><p class="reward-name" id="board-status">Class progress is loading…</p><p class="small">'+esc(classroom.room||'Classroom')+' · Shared classroom display</p>'+(profile.role==='STUDENT'?'':'<button class="board-cta" data-action="board-checkin">Record arrivals</button>')+'</section></div>';refreshBoard().catch(e=>toast(errMsg(e)))}
async function refreshBoard(){if(!dayRow){document.querySelector('#board-status').textContent='Today’s class session is not available.';return}const [a,goal]=await Promise.all([supabase.from('arrivals').select('status').eq('class_day_id',dayRow.id),dailyGoal()]);if(a.error)throw a.error;const early=(a.data||[]).filter(x=>x.status==='EARLY').length,target=goal.target,done=early>=target;$('#board-progress').innerHTML=early+' <span>/ '+target+'</span>';$('#board-fill').style.width=Math.min(100,early/target*100)+'%';$('#board-status').textContent=done?'🎉 EARLYPASS UNLOCKED! · '+goal.reward:(target-early)+' more early arrivals needed';setTimeout(()=>{if(page==='board')refreshBoard().catch(()=>{})},30000)}

function $(s){return document.querySelector(s)}
function modal(title,body){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><header><h2>${title}</h2><button class="secondary" data-close>Close</button></header><div class="modal-body">${body}</div></section></div>`;root.querySelector('[data-close]').onclick=()=>root.innerHTML='';return root.querySelector('.modal')}
function formHtml(fields){return `<form class="form-row">${fields.map(([label,name,type='text',value='',required=true])=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`).join('')}<button class="primary wide" style="grid-column:1/-1">Save</button></form>`}
async function action(a,id){if(a==='board-fullscreen'){document.body.classList.add('board-fullscreen');document.documentElement.requestFullscreen?.().catch(()=>{});return}if(a==='board-exit'){document.body.classList.remove('board-fullscreen');if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});return}if(a==='choose-weekday'){selectedWeekday=Number(id);render();return}if(a==='attendance'){page='attendance';render();return}if(a==='board'){page='board';boardSession=null;render();return}if(a==='history'){page='history';render();return}
if(a==='add-student'||a==='edit-student'){const s=students.find(x=>x.id===id)||{},m=modal(a==='add-student'?'Add student':'Edit student',formHtml([['Student name','name','text',s.name||''],['Roll number','roll_number','text',s.roll_number||''],['Student ID','student_code','text',s.student_code||'',false],['Email (optional)','email','email',s.email||'',false]]));m.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));const payload={name:v.name.trim(),roll_number:v.roll_number.trim(),student_code:v.student_code.trim()||'EP-'+classroom.class_name+classroom.section+'-'+crypto.randomUUID().slice(0,8).toUpperCase(),email:v.email||null,school_id:classroom.school_id,classroom_id:classroom.id};const q=s.id?await supabase.from('students').update(payload).eq('id',s.id):await supabase.from('students').insert(payload);if(q.error){showError(errMsg(q.error));return}$('#modal-root').innerHTML='';toast('Student saved.');render()};return}
if(a==='add-period'||a==='edit-period'){const p=periods.find(x=>x.id===id)||{},wd=p.weekday&&Number(p.weekday)!==0?Number(p.weekday):selectedWeekday,existing=periods.filter(x=>Number(x.weekday||0)===wd),nextPosition=existing.reduce((n,x)=>Math.max(n,Number(x.position)||0),0)+1,m=modal(a==='add-period'?'Add period':'Edit period',formHtml([['Period name','name','text',p.name||'Period '+nextPosition],['Subject','subject','text',p.subject||''],['Start time','starts_at','time',time(p.starts_at)||'08:30'],['End time','ends_at','time',time(p.ends_at)||'09:15'],['Teacher','teacher_name','text',p.teacher_name||profile.display_name],['Room','room','text',p.room||classroom.room]]));m.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));const payload={...v,weekday:wd,position:p.position||nextPosition,classroom_id:classroom.id};const q=p.id?await supabase.from('periods').update(payload).eq('id',p.id):await supabase.from('periods').insert(payload);if(q.error){showError(errMsg(q.error));return}$('#modal-root').innerHTML='';render()};return}
if(a==='delete-period'){if(!confirm('Delete this period? Existing historical attendance may prevent deletion.'))return;const {error}=await supabase.from('periods').delete().eq('id',id);if(error)showError(errMsg(error));else{toast('Period deleted.');render()}return}
if(a==='cycle'){if(profile.role==='STUDENT')return;let [student_id,period_id]=id.split('|'),statuses=['PRESENT','LATE','ABSENT','EXCUSED'],{data:old}=await supabase.from('attendance').select('status').eq('class_day_id',dayRow.id).eq('student_id',student_id).eq('period_id',period_id).maybeSingle(),next=statuses[(statuses.indexOf(old?.status)+1)%statuses.length];const {error}=await supabase.from('attendance').upsert({class_day_id:dayRow.id,student_id,period_id,status:next,marked_by:user.id},{onConflict:'class_day_id,student_id,period_id'});if(error)showError(errMsg(error));else render();return}
if(a==='edit-goal'){const goal=await dailyGoal(),m=modal('Set today’s minimum',formHtml([['Minimum early check-ins','target','number',goal.target],['Today’s reward','reward','text',goal.reward],['Teacher-only follow-up if the minimum is missed','follow_up','text',goal.follow_up]]));m.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget)),target=Math.max(1,Number(v.target));const q=await supabase.from('earlypass_rewards').upsert({class_day_id:dayRow.id,target,reward:v.reward.trim()||rewardForDate(today()),manual_target:true,follow_up:v.follow_up.trim()||'A brief reflection and a fresh start tomorrow.'},{onConflict:'class_day_id'});if(q.error){showError(errMsg(q.error));return}$('#modal-root').innerHTML='';toast('Today’s goal and activity saved.');render()};return}
if(a==='review-follow-up'){if(profile.role==='STUDENT')return;const first=periodsForDay(weekdayOf(today()))[0];if(!dayRow||!first){showError('No first-period attendance is available yet.');return}const [att,arr]=await Promise.all([supabase.from('attendance').select('student_id,status').eq('class_day_id',dayRow.id).eq('period_id',first.id).in('status',['PRESENT','LATE']),supabase.from('arrivals').select('student_id,status').eq('class_day_id',dayRow.id).eq('status','EARLY')]);if(att.error||arr.error){showError(errMsg(att.error||arr.error));return}const early=new Set((arr.data||[]).map(x=>x.student_id)),present=new Set((att.data||[]).map(x=>x.student_id)),needsFollowUp=students.filter(x=>present.has(x.id)&&!early.has(x.id)),goal=await dailyGoal(),list=needsFollowUp.length?'<ul>'+needsFollowUp.map(x=>'<li>'+esc(x.roll_number)+' · '+esc(x.name)+'</li>').join('')+'</ul>':'<p>No present students are missing an early check-in.</p>';modal('Private teacher follow-up','<p><b>Suggested class response:</b> '+esc(goal.follow_up)+'</p><p>This list is private to the teacher. Only students marked present or late in Period 1 who do not have an early arrival are included. Absent or excused students are not included.</p>'+list);return}
if(a==='edit-join-code'){const current=user?.user_metadata?.class_join_code||'',m=modal('Class join code',formHtml([['Code students can use to join','class_join_code','text',current||'8A-2026']]));const input=m.querySelector('input[name="class_join_code"]');input.minLength=6;input.maxLength=24;m.querySelector('form').onsubmit=async e=>{e.preventDefault();const code=input.value.trim().toUpperCase().replace(/\s+/g,'');if(code.length<6){showError('Use at least 6 characters.');return}const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(code)),hash=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');const saved=await supabase.from('classrooms').update({access_code_hash:hash}).eq('id',classroom.id);if(saved.error){showError(errMsg(saved.error));return}const auth=await supabase.auth.updateUser({data:{...user.user_metadata,class_join_code:code}});if(auth.error){showError(errMsg(auth.error));return}user=auth.data.user||user;$('#modal-root').innerHTML='';toast('Class join code saved. Share it only with your class.');render()};return}
if(a==='edit-class'){const m=modal('Edit class settings',formHtml([['Class start','class_start','time',time(classroom.class_start)],['Early arrival window (minutes)','early_window_minutes','number',classroom.early_window_minutes],['Room','room','text',classroom.room||'']]));m.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));const {error}=await supabase.from('classrooms').update({...v,early_window_minutes:Number(v.early_window_minutes)}).eq('id',classroom.id);if(error){showError(errMsg(error));return}Object.assign(classroom,v);$('#modal-root').innerHTML='';render()};return}

if(a==='board-checkin'){if(profile.role==='STUDENT')return;if(!dayRow){showError('Today’s class session is unavailable.');return}const m=modal('Record today’s arrivals','<p class="muted">Select everyone who has arrived. Early check-ins move the shared goal; personal attendance is not shown on the board.</p><label class="checkin-select-all"><input type="checkbox" id="check-all">Select all available students</label><div class="checkin-roster">'+students.map(s=>'<label class="checkin-person"><input type="checkbox" name="checkin-student" value="'+esc(s.id)+'"><span><b>'+esc(s.roll_number)+' · '+esc(s.name)+'</b></span></label>').join('')+'</div><button class="primary wide" id="send-checkin">Save selected check-ins</button>');m.querySelector('#check-all').onchange=e=>{m.querySelectorAll('input[name="checkin-student"]:not(:disabled)').forEach(x=>x.checked=e.target.checked)};m.querySelector('#send-checkin').onclick=async()=>{const selected=[...m.querySelectorAll('input[name="checkin-student"]:checked')].map(x=>x.value);if(!selected.length){showError('Select at least one student.');return}const current=new Date(),nowTime=String(current.getHours()).padStart(2,'0')+':'+String(current.getMinutes()).padStart(2,'0'),settings=daySettings(today()),cutoff=String(settings.class_start||classroom.class_start).slice(0,5),earlyBy=Number(settings.early_window_minutes||15),mins=x=>{const q=String(x).split(':').map(Number);return q[0]*60+q[1]},status=mins(nowTime)<mins(cutoff)-earlyBy?'EARLY':mins(nowTime)<=mins(cutoff)?'ON_TIME':'LATE',records=selected.map(student_id=>({class_day_id:dayRow.id,student_id,arrived_at:current.toISOString(),status,recorded_by:user.id})),result=await supabase.from('arrivals').upsert(records,{onConflict:'class_day_id,student_id',ignoreDuplicates:true}).select('student_id');if(result.error){showError(errMsg(result.error));return}$('#modal-root').innerHTML='';const amount=result.data?.length||0;toast(amount?amount+' check-in'+(amount===1?'':'s')+' saved as '+status+'.'+(status==='EARLY'?'':' Only early arrivals increase the EarlyPass goal.'):'No new check-ins were added; previously saved arrivals stay recorded.');await render()};return}

}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)action(a.dataset.action,a.dataset.id).catch(err=>showError(errMsg(err)))});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('board-fullscreen')});
supabase.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){profile=null;login()}});
if(cfg?.supabaseUrl&&cfg?.supabasePublishableKey)boot().catch(e=>{login();showError(errMsg(e))});else location.hash==='#signup'?signup():login();
window.addEventListener('hashchange',()=>{if(!profile)location.hash==='#signup'?signup():login()});
